export function dirFor(lang) {
  const m = LANG_META[lang];
  return (m && m.dir === 'rtl') ? 'rtl' : 'ltr';
}

// navigator.languages -> supported code. 3-step: exact -> base-language -> English.
export function resolveLang(navs) {
  const list = Array.isArray(navs) ? navs : [navs];
  for (const raw of list) {
    if (!raw) continue;
    const low = String(raw).toLowerCase();
    if (SUPPORTED.includes(low)) return low;            // exact, e.g. 'pt'
    const base = low.split('-')[0];
    if (base === 'zh') return 'zh';                      // any Chinese -> Simplified
    if (SUPPORTED.includes(base)) return base;           // 'pt-br' -> 'pt'
  }
  return 'en';                                           // unsupported (e.g. Finnish) -> English
}

// makeTT(lang) -> tt(englishKey) returning the translation, falling back to the key itself.
export function makeTT(lang) {
  const table = DICT[lang] || {};
  return function tt(key) {
    if (key == null) return key;
    const v = table[key];
    return (v != null) ? v : key;   // fallback: show the English key verbatim
  };
}
